// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser.sparql;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.Service;
import org.eclipse.rdf4j.query.algebra.helpers.AbstractQueryModelVisitor;
import org.junit.jupiter.api.Test;

class BlankNodeReferenceOwnershipParserTest {
	@Test
	void identicalLocalAndServiceReferencesKeepSeparateOwners() {
		var parsed = new SPARQLParser().parseQuery("SELECT ?local WHERE { "
				+ "VALUES ?local { <_:same> } "
				+ "SERVICE <urn:service> { <_:same> <urn:p> ?remote } }", null);
		List<BindingSetAssignment> values = new ArrayList<>();
		List<Service> services = new ArrayList<>();
		parsed.getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment node) {
				values.add(node);
			}

			@Override
			public void meet(Service node) {
				services.add(node);
				super.meet(node);
			}
		});

		assertThat(values).hasSize(1);
		assertThat(values.get(0).getBindingSets()).hasSize(1);
		assertThat(values.get(0).getBindingSets().iterator().next().getValue("local"))
				.isEqualTo(SimpleValueFactory.getInstance().createBNode("same"));
		assertThat(services).hasSize(1);
		assertThat(services.get(0).hasBNodeReferences()).isTrue();
		assertThat(services.get(0).getReservedBNodeIDs()).containsExactly("same");
	}
}
